-- Turkey story arc: 3 stories tracing the mandate from its April 2014
-- launch, through the 2023 e-Irsaliye expansion, to the January 2026
-- threshold tightening. Sourced from sovos.com's e-Transformation
-- Turkey timeline and fiscal-requirements.com's 2026 threshold
-- coverage, cross-checked against each other for dates and figures.

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2014-04-01-turkey-efatura-mandatory', '2014-04-01', '2014-04', 'e-Fatura became mandatory for Turkish companies with turnover exceeding TRY 5 million, alongside several sectors required regardless of size -- the start of one of the longest-running e-invoicing mandates this tracker covers.', '<h3>🇹🇷 e-Fatura becomes mandatory in Turkey</h3>
<p>From 1 April 2014, Turkey''s Revenue Administration (Gelir İdaresi Başkanlığı, GİB) made e-Fatura mandatory for companies with turnover exceeding TRY 5 million, alongside several sectors required regardless of size -- energy companies, fruit and vegetable wholesalers, online marketplaces and service providers, and importers.</p>
<p>e-Fatura works as a clearance model: the seller submits a UBL-TR structured, digitally-signed invoice to GİB''s central platform, which validates it and distributes the cleared invoice to the registered buyer -- the seller and buyer never exchange the document directly. This built on e-Transformation groundwork GİB had been laying since 2012.</p>
<p>Twelve years on, e-Fatura remains one of the most mature and closely-studied e-invoicing regimes in the world -- a reference point other countries'' clearance-model mandates, including several elsewhere in this tracker, are often compared against.</p>', 'https://sovos.com/en-gb/vat/tax-rules/e-transformation-turkey/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2014-04-01-turkey-efatura-mandatory', id FROM countries WHERE name_en = 'Turkey';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2014-04-01-turkey-efatura-mandatory', 'en', 'e-Fatura becomes mandatory in Turkey', 'e-Fatura became mandatory for Turkish companies with turnover exceeding TRY 5 million, alongside several sectors required regardless of size -- the start of one of the longest-running e-invoicing mandates this tracker covers.', '<h3>🇹🇷 e-Fatura becomes mandatory in Turkey</h3>
<p>From 1 April 2014, Turkey''s Revenue Administration (Gelir İdaresi Başkanlığı, GİB) made e-Fatura mandatory for companies with turnover exceeding TRY 5 million, alongside several sectors required regardless of size -- energy companies, fruit and vegetable wholesalers, online marketplaces and service providers, and importers.</p>
<p>e-Fatura works as a clearance model: the seller submits a UBL-TR structured, digitally-signed invoice to GİB''s central platform, which validates it and distributes the cleared invoice to the registered buyer -- the seller and buyer never exchange the document directly. This built on e-Transformation groundwork GİB had been laying since 2012.</p>
<p>Twelve years on, e-Fatura remains one of the most mature and closely-studied e-invoicing regimes in the world -- a reference point other countries'' clearance-model mandates, including several elsewhere in this tracker, are often compared against.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2014-04-01-turkey-efatura-mandatory', 'es', 'La e-Fatura se vuelve obligatoria en Turquía', 'La e-Fatura se volvió obligatoria para las empresas turcas con una facturación superior a 5 millones de TRY, junto con varios sectores obligados con independencia de su tamaño -- el inicio de uno de los mandatos de facturación electrónica más antiguos que cubre este seguimiento.', '<h3>🇹🇷 La e-Fatura se vuelve obligatoria en Turquía</h3>
<p>A partir del 1 de abril de 2014, la Administración Tributaria de Turquía (Gelir İdaresi Başkanlığı, GİB) hizo obligatoria la e-Fatura para las empresas con una facturación superior a 5 millones de TRY, junto con varios sectores obligados con independencia de su tamaño: empresas energéticas, mayoristas de frutas y verduras, mercados y proveedores de servicios en línea, e importadores.</p>
<p>La e-Fatura funciona como un modelo de validación: el vendedor envía una factura estructurada en UBL-TR y firmada digitalmente a la plataforma central de la GİB, que la valida y distribuye la factura validada al comprador registrado -- vendedor y comprador nunca intercambian el documento directamente. Esto se apoyó en los trabajos de transformación digital que la GİB venía realizando desde 2012.</p>
<p>Doce años después, la e-Fatura sigue siendo uno de los regímenes de facturación electrónica más maduros y estudiados del mundo -- un punto de referencia con el que a menudo se comparan los mandatos de otros países basados en modelos de validación, incluidos varios de este mismo seguimiento.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2014-04-01-turkey-efatura-mandatory', 'de', 'e-Fatura wird in der Türkei verpflichtend', 'e-Fatura wurde für türkische Unternehmen mit einem Umsatz von über 5 Millionen TRY verpflichtend, zusammen mit mehreren Branchen, die unabhängig von ihrer Größe verpflichtet sind -- der Beginn einer der am längsten bestehenden E-Invoicing-Pflichten, die dieser Tracker erfasst.', '<h3>🇹🇷 e-Fatura wird in der Türkei verpflichtend</h3>
<p>Ab dem 1. April 2014 machte die türkische Steuerbehörde (Gelir İdaresi Başkanlığı, GİB) e-Fatura für Unternehmen mit einem Umsatz von über 5 Millionen TRY verpflichtend, zusammen mit mehreren Branchen, die unabhängig von ihrer Größe verpflichtet sind -- Energieunternehmen, Obst- und Gemüsegroßhändler, Online-Marktplätze und -Dienstleister sowie Importeure.</p>
<p>e-Fatura funktioniert als Freigabemodell: Der Verkäufer übermittelt eine strukturierte, digital signierte UBL-TR-Rechnung an die zentrale Plattform der GİB, die sie prüft und die freigegebene Rechnung an den registrierten Käufer verteilt -- Verkäufer und Käufer tauschen das Dokument nie direkt aus. Dies baute auf den E-Transformations-Grundlagen auf, die die GİB seit 2012 gelegt hatte.</p>
<p>Zwölf Jahre später ist e-Fatura nach wie vor eines der ausgereiftesten und meistuntersuchten E-Invoicing-Regime der Welt -- ein Referenzpunkt, an dem die Freigabemodelle anderer Länder, darunter mehrere in diesem Tracker, häufig gemessen werden.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2014-04-01-turkey-efatura-mandatory', 'fr', 'L''e-Fatura devient obligatoire en Turquie', 'L''e-Fatura est devenue obligatoire pour les entreprises turques dont le chiffre d''affaires dépasse 5 millions de TRY, ainsi que pour plusieurs secteurs soumis à l''obligation quelle que soit leur taille -- le début de l''une des obligations de facturation électronique les plus anciennes couvertes par ce suivi.', '<h3>🇹🇷 L''e-Fatura devient obligatoire en Turquie</h3>
<p>À compter du 1er avril 2014, l''administration fiscale turque (Gelir İdaresi Başkanlığı, GİB) a rendu l''e-Fatura obligatoire pour les entreprises dont le chiffre d''affaires dépasse 5 millions de TRY, ainsi que pour plusieurs secteurs soumis à l''obligation quelle que soit leur taille -- sociétés énergétiques, grossistes en fruits et légumes, places de marché et prestataires de services en ligne, et importateurs.</p>
<p>L''e-Fatura fonctionne selon un modèle de validation : le vendeur transmet une facture structurée au format UBL-TR et signée électroniquement à la plateforme centrale de la GİB, qui la valide et distribue la facture validée à l''acheteur enregistré -- vendeur et acheteur n''échangent jamais directement le document. Cette étape s''appuyait sur les travaux de transformation numérique menés par la GİB depuis 2012.</p>
<p>Douze ans plus tard, l''e-Fatura reste l''un des régimes de facturation électronique les plus matures et les plus étudiés au monde -- une référence à laquelle sont souvent comparés les modèles de validation d''autres pays, y compris plusieurs figurant dans ce même suivi.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2023-07-01-turkey-eirsaliye-mandatory', '2023-07-01', '2023-07', 'e-İrsaliye, Turkey''s electronic waybill for goods movement, became mandatory for taxpayers with revenue exceeding TRY 10 million -- a separate document from e-Fatura, tracked against its own threshold.', '<h3>🇹🇷 e-İrsaliye becomes mandatory for larger Turkish taxpayers</h3>
<p>From 1 July 2023, e-İrsaliye -- Turkey''s electronic dispatch note/waybill accompanying the physical movement of goods -- became mandatory for taxpayers with revenue exceeding TRY 10 million, with voluntary adoption open to everyone else.</p>
<p>e-İrsaliye documents the goods movement itself rather than the sale, so it sits alongside e-Fatura rather than replacing any part of it -- a business can be fully e-Fatura compliant and still need to onboard e-İrsaliye separately once it crosses this threshold. The two systems are tracked against different revenue thresholds, so crossing one doesn''t automatically mean a business has crossed the other.</p>
<p>The addition extended Turkey''s digital-reporting footprint beyond the invoice itself, following the same pattern as e-Defter (electronic ledgers) before it -- a steady expansion of what GİB tracks electronically, one document type at a time.</p>', 'https://sovos.com/en-gb/vat/tax-rules/e-transformation-turkey/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2023-07-01-turkey-eirsaliye-mandatory', id FROM countries WHERE name_en = 'Turkey';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-01-turkey-eirsaliye-mandatory', 'en', 'e-İrsaliye becomes mandatory for larger Turkish taxpayers', 'e-İrsaliye, Turkey''s electronic waybill for goods movement, became mandatory for taxpayers with revenue exceeding TRY 10 million -- a separate document from e-Fatura, tracked against its own threshold.', '<h3>🇹🇷 e-İrsaliye becomes mandatory for larger Turkish taxpayers</h3>
<p>From 1 July 2023, e-İrsaliye -- Turkey''s electronic dispatch note/waybill accompanying the physical movement of goods -- became mandatory for taxpayers with revenue exceeding TRY 10 million, with voluntary adoption open to everyone else.</p>
<p>e-İrsaliye documents the goods movement itself rather than the sale, so it sits alongside e-Fatura rather than replacing any part of it -- a business can be fully e-Fatura compliant and still need to onboard e-İrsaliye separately once it crosses this threshold. The two systems are tracked against different revenue thresholds, so crossing one doesn''t automatically mean a business has crossed the other.</p>
<p>The addition extended Turkey''s digital-reporting footprint beyond the invoice itself, following the same pattern as e-Defter (electronic ledgers) before it -- a steady expansion of what GİB tracks electronically, one document type at a time.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-01-turkey-eirsaliye-mandatory', 'es', 'e-İrsaliye se vuelve obligatorio para los grandes contribuyentes turcos', 'El e-İrsaliye, el albarán electrónico de Turquía para el movimiento de mercancías, se volvió obligatorio para los contribuyentes con una facturación superior a 10 millones de TRY -- un documento distinto de la e-Fatura, controlado frente a su propio umbral.', '<h3>🇹🇷 e-İrsaliye se vuelve obligatorio para los grandes contribuyentes turcos</h3>
<p>A partir del 1 de julio de 2023, el e-İrsaliye -- el albarán/nota de despacho electrónico de Turquía que acompaña el movimiento físico de las mercancías -- se volvió obligatorio para los contribuyentes con una facturación superior a 10 millones de TRY, quedando abierta la adhesión voluntaria para el resto.</p>
<p>El e-İrsaliye documenta el movimiento de la mercancía en sí, no la venta, por lo que coexiste con la e-Fatura en lugar de sustituir ninguna parte de ella -- una empresa puede cumplir plenamente con la e-Fatura y aun así necesitar implementar el e-İrsaliye por separado al superar este umbral. Ambos sistemas se controlan frente a umbrales de facturación distintos, por lo que superar uno no implica automáticamente haber superado el otro.</p>
<p>Esta incorporación amplió el alcance del reporte digital de Turquía más allá de la propia factura, siguiendo el mismo patrón que antes marcó el e-Defter (libros contables electrónicos) -- una expansión constante de lo que la GİB controla electrónicamente, un tipo de documento a la vez.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-01-turkey-eirsaliye-mandatory', 'de', 'e-İrsaliye wird für größere türkische Steuerpflichtige verpflichtend', 'e-İrsaliye, der türkische elektronische Lieferschein für Warenbewegungen, wurde für Steuerpflichtige mit einem Umsatz von über 10 Millionen TRY verpflichtend -- ein von e-Fatura getrenntes Dokument, das anhand eines eigenen Schwellenwerts erfasst wird.', '<h3>🇹🇷 e-İrsaliye wird für größere türkische Steuerpflichtige verpflichtend</h3>
<p>Ab dem 1. Juli 2023 wurde e-İrsaliye -- der elektronische Liefer-/Versandschein der Türkei, der die physische Warenbewegung begleitet -- für Steuerpflichtige mit einem Umsatz von über 10 Millionen TRY verpflichtend; für alle anderen bleibt die freiwillige Nutzung offen.</p>
<p>e-İrsaliye dokumentiert die Warenbewegung selbst und nicht den Verkauf, steht also neben e-Fatura, statt einen Teil davon zu ersetzen -- ein Unternehmen kann vollständig e-Fatura-konform sein und muss dennoch e-İrsaliye separat einführen, sobald es diese Schwelle überschreitet. Beide Systeme werden anhand unterschiedlicher Umsatzschwellen erfasst, sodass das Überschreiten des einen nicht automatisch bedeutet, dass auch der andere überschritten wurde.</p>
<p>Diese Erweiterung dehnte Türkiyes digitale Meldepflichten über die Rechnung selbst hinaus aus und folgte damit demselben Muster wie zuvor e-Defter (elektronische Bücher) -- eine stetige Ausweitung dessen, was die GİB elektronisch erfasst, jeweils einen Dokumenttyp nach dem anderen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-01-turkey-eirsaliye-mandatory', 'fr', 'L''e-İrsaliye devient obligatoire pour les plus grands contribuables turcs', 'L''e-İrsaliye, le bon de livraison électronique turc pour le mouvement des marchandises, est devenu obligatoire pour les contribuables dont le chiffre d''affaires dépasse 10 millions de TRY -- un document distinct de l''e-Fatura, suivi par rapport à son propre seuil.', '<h3>🇹🇷 L''e-İrsaliye devient obligatoire pour les plus grands contribuables turcs</h3>
<p>À compter du 1er juillet 2023, l''e-İrsaliye -- le bon de livraison/d''expédition électronique turc accompagnant le mouvement physique des marchandises -- est devenu obligatoire pour les contribuables dont le chiffre d''affaires dépasse 10 millions de TRY, l''adoption volontaire restant ouverte à tous les autres.</p>
<p>L''e-İrsaliye documente le mouvement de la marchandise elle-même, et non la vente, de sorte qu''il s''ajoute à l''e-Fatura plutôt que de s''y substituer -- une entreprise peut être pleinement conforme à l''e-Fatura et devoir malgré tout mettre en place l''e-İrsaliye séparément une fois ce seuil franchi. Les deux systèmes sont suivis par rapport à des seuils de chiffre d''affaires différents, si bien que franchir l''un ne signifie pas automatiquement avoir franchi l''autre.</p>
<p>Cet ajout a étendu le périmètre de déclaration numérique de la Turquie au-delà de la facture elle-même, suivant le même schéma que l''e-Defter (livres comptables électroniques) auparavant -- une extension constante de ce que la GİB suit électroniquement, un type de document à la fois.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-turkey-earsiv-floor-removed', '2026-01-01', '2026-01', 'Turkey removed the monetary floor on mandatory e-Arşiv issuance entirely and tightened its 2026 e-Fatura thresholds -- TRY 3 million generally, TRY 500,000 for e-commerce, real estate, motor vehicles, and licensed accommodation.', '<h3>🇹🇷 Turkey removes e-Arşiv''s monetary floor for 2026</h3>
<p>From 1 January 2026, Turkey''s Revenue Administration (GİB) removed the previous monetary floor on mandatory e-Arşiv issuance entirely -- any invoice to a recipient not registered for e-Fatura must now be issued electronically as an e-Arşiv invoice regardless of its value, closing what had been a real gap for small transactions.</p>
<p>Alongside this, the 2026 e-Fatura turnover threshold based on 2025 revenue is TRY 3 million generally, with a lower TRY 500,000 threshold applying to e-commerce businesses, and real-estate, motor-vehicle, and licensed-accommodation transactions. Businesses crossing either threshold on 2025 revenue must register for e-Fatura by 1 July 2026.</p>
<p>Twelve years after e-Fatura''s launch, this is the latest step in a mandate that has tightened steadily rather than all at once -- each year narrowing the gap between "structured e-invoicing" and "every invoice, regardless of size."</p>', 'https://www.fiscal-requirements.com/news/5764-turkeys-2026-e-invoice-deadline-applies-to-businesses-exceeding-2025-turnover-thresholds', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-01-01-turkey-earsiv-floor-removed', id FROM countries WHERE name_en = 'Turkey';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-turkey-earsiv-floor-removed', 'en', 'Turkey removes e-Arşiv''s monetary floor for 2026', 'Turkey removed the monetary floor on mandatory e-Arşiv issuance entirely and tightened its 2026 e-Fatura thresholds -- TRY 3 million generally, TRY 500,000 for e-commerce, real estate, motor vehicles, and licensed accommodation.', '<h3>🇹🇷 Turkey removes e-Arşiv''s monetary floor for 2026</h3>
<p>From 1 January 2026, Turkey''s Revenue Administration (GİB) removed the previous monetary floor on mandatory e-Arşiv issuance entirely -- any invoice to a recipient not registered for e-Fatura must now be issued electronically as an e-Arşiv invoice regardless of its value, closing what had been a real gap for small transactions.</p>
<p>Alongside this, the 2026 e-Fatura turnover threshold based on 2025 revenue is TRY 3 million generally, with a lower TRY 500,000 threshold applying to e-commerce businesses, and real-estate, motor-vehicle, and licensed-accommodation transactions. Businesses crossing either threshold on 2025 revenue must register for e-Fatura by 1 July 2026.</p>
<p>Twelve years after e-Fatura''s launch, this is the latest step in a mandate that has tightened steadily rather than all at once -- each year narrowing the gap between "structured e-invoicing" and "every invoice, regardless of size."</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-turkey-earsiv-floor-removed', 'es', 'Turquía elimina el umbral mínimo de la e-Arşiv para 2026', 'Turquía eliminó por completo el umbral mínimo para la emisión obligatoria de e-Arşiv y endureció sus umbrales de e-Fatura para 2026 -- 3 millones de TRY con carácter general, 500.000 TRY para comercio electrónico, inmobiliario, vehículos a motor y alojamiento con licencia.', '<h3>🇹🇷 Turquía elimina el umbral mínimo de la e-Arşiv para 2026</h3>
<p>A partir del 1 de enero de 2026, la Administración Tributaria de Turquía (GİB) eliminó por completo el anterior umbral mínimo para la emisión obligatoria de e-Arşiv -- cualquier factura dirigida a un destinatario no registrado en e-Fatura debe emitirse ahora electrónicamente como factura e-Arşiv, sea cual sea su importe, cerrando lo que hasta entonces era un vacío real para las operaciones de bajo valor.</p>
<p>Junto con esto, el umbral de facturación de e-Fatura para 2026, calculado sobre los ingresos de 2025, es de 3 millones de TRY con carácter general, con un umbral inferior de 500.000 TRY aplicable a las empresas de comercio electrónico y a las operaciones inmobiliarias, de vehículos a motor y de alojamiento con licencia. Las empresas que superen cualquiera de los dos umbrales según los ingresos de 2025 deben registrarse en e-Fatura antes del 1 de julio de 2026.</p>
<p>Doce años después del lanzamiento de la e-Fatura, este es el último paso de un mandato que se ha endurecido de forma constante en lugar de todo a la vez -- cada año reduce la distancia entre "facturación electrónica estructurada" y "toda factura, sin importar su tamaño".</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-turkey-earsiv-floor-removed', 'de', 'Türkiye streicht die Wertgrenze der e-Arşiv für 2026', 'Die Türkei hob die bisherige Wertgrenze für die verpflichtende e-Arşiv-Ausstellung vollständig auf und verschärfte ihre e-Fatura-Schwellenwerte für 2026 -- 3 Millionen TRY allgemein, 500.000 TRY für E-Commerce, Immobilien, Kraftfahrzeuge und lizenzierte Beherbergung.', '<h3>🇹🇷 Türkiye streicht die Wertgrenze der e-Arşiv für 2026</h3>
<p>Ab dem 1. Januar 2026 hob die türkische Steuerbehörde (GİB) die bisherige Wertgrenze für die verpflichtende e-Arşiv-Ausstellung vollständig auf -- jede Rechnung an einen nicht bei e-Fatura registrierten Empfänger muss nun unabhängig vom Betrag elektronisch als e-Arşiv-Rechnung ausgestellt werden, womit eine bislang bestehende Lücke bei Kleinbeträgen geschlossen wird.</p>
<p>Gleichzeitig liegt die e-Fatura-Umsatzschwelle für 2026, bezogen auf den Umsatz 2025, allgemein bei 3 Millionen TRY, mit einer niedrigeren Schwelle von 500.000 TRY für E-Commerce-Unternehmen sowie für Immobilien-, Kraftfahrzeug- und lizenzierte Beherbergungsgeschäfte. Unternehmen, die auf Basis des Umsatzes 2025 eine der beiden Schwellen überschreiten, müssen sich bis zum 1. Juli 2026 für e-Fatura registrieren.</p>
<p>Zwölf Jahre nach dem Start von e-Fatura ist dies der jüngste Schritt einer Pflicht, die sich stetig statt auf einen Schlag verschärft hat -- Jahr für Jahr verkleinert sich die Lücke zwischen „strukturiertem E-Invoicing" und „jeder Rechnung, unabhängig von ihrer Höhe".</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-turkey-earsiv-floor-removed', 'fr', 'La Turquie supprime le seuil minimal de l''e-Arşiv pour 2026', 'La Turquie a totalement supprimé le seuil minimal auparavant applicable à l''émission obligatoire de l''e-Arşiv et a resserré ses seuils d''e-Fatura pour 2026 -- 3 millions de TRY de manière générale, 500 000 TRY pour le commerce électronique, l''immobilier, les véhicules à moteur et l''hébergement agréé.', '<h3>🇹🇷 La Turquie supprime le seuil minimal de l''e-Arşiv pour 2026</h3>
<p>À compter du 1er janvier 2026, l''administration fiscale turque (GİB) a totalement supprimé le seuil minimal auparavant applicable à l''émission obligatoire de l''e-Arşiv -- toute facture adressée à un destinataire non enregistré à l''e-Fatura doit désormais être émise électroniquement sous forme de facture e-Arşiv, quel que soit son montant, comblant ainsi une véritable lacune pour les opérations de faible valeur.</p>
<p>Parallèlement, le seuil de chiffre d''affaires de l''e-Fatura pour 2026, calculé sur les revenus de 2025, est fixé à 3 millions de TRY de manière générale, avec un seuil inférieur de 500 000 TRY applicable aux entreprises de commerce électronique ainsi qu''aux opérations immobilières, de véhicules à moteur et d''hébergement agréé. Les entreprises franchissant l''un ou l''autre seuil sur la base des revenus 2025 doivent s''inscrire à l''e-Fatura avant le 1er juillet 2026.</p>
<p>Douze ans après le lancement de l''e-Fatura, il s''agit de la dernière étape d''une obligation qui s''est durcie progressivement plutôt que d''un seul coup -- chaque année réduisant l''écart entre « facturation électronique structurée » et « chaque facture, quelle que soit sa taille ».</p>');
